import{_ as e,o as i,c as t,ag as r}from"./chunks/framework.B3amng90.js";const o="/abu-aigc-guide/screenshots/marketing.webp",l="/abu-aigc-guide/screenshots/marketing-remix.webp",s="/abu-aigc-guide/examples/marketing-case.webp",_=JSON.parse('{"title":"爆款：为商品制作短视频","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/marketing.md","filePath":"workflows/marketing.md"}'),n={name:"workflows/marketing.md"};function p(g,a,c,m,d,h){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="爆款-为商品制作短视频" tabindex="-1">爆款：为商品制作短视频 <a class="header-anchor" href="#爆款-为商品制作短视频" aria-label="Permalink to &quot;爆款：为商品制作短视频&quot;">​</a></h1><p>进入侧栏 <strong>爆款</strong>，围绕商品图片、卖点或参考内容制作短视频脚本与镜头素材。</p><h2 id="准备商品资料" tabindex="-1">准备商品资料 <a class="header-anchor" href="#准备商品资料" aria-label="Permalink to &quot;准备商品资料&quot;">​</a></h2><ol><li>选择 <strong>创意</strong>，让系统围绕商品生成新脚本；或选择 <strong>复刻</strong>，根据参考内容整理相近的节奏和结构。</li><li>上传同一商品的 <strong>1–4 张商品图</strong>。也可以添加支持的平台链接作为参考，或按需上传模特图。参考视频是否可用取决于当前模型。</li><li>在商品描述中填写准确的品类、功能、材质和卖点。不要把 AI 推测出的信息当成已经核实的商品事实。</li><li>选择投放平台和创意角度，检查页面列出的生成参数。</li></ol><p><a href="/abu-aigc-guide/screenshots/marketing.webp"><img src="'+o+'" alt="爆款创意模式的商品图、模特图、商品描述和投放平台入口" loading="lazy"></a></p><p><em>用「创意」从商品资料开始写脚本。点击截图可查看大图。</em></p><p><a href="/abu-aigc-guide/screenshots/marketing-remix.webp"><img src="'+l+'" alt="爆款复刻模式的参考链接和素材区" loading="lazy"></a></p><p><em>用「复刻」沿用参考内容的节奏和结构。</em></p><h2 id="完整案例-先写商品卖点-再检查成片" tabindex="-1">完整案例：先写商品卖点，再检查成片 <a class="header-anchor" href="#完整案例-先写商品卖点-再检查成片" aria-label="Permalink to &quot;完整案例：先写商品卖点，再检查成片&quot;">​</a></h2><p>可以先用不含品牌和个人信息的商品描述练习流程：</p><blockquote><p>一款轻量防泼水通勤双肩包，主仓可放 14 英寸电脑，侧袋方便取水杯，肩带柔软，适合城市通勤。画面干净明亮，突出容量、收纳和背负舒适度。</p></blockquote><p>实际操作时按这条链路检查：</p><ol><li>上传同一商品的 1–4 张图，确保正面、侧面和细节图展示的是同一件商品。</li><li>在商品描述中只写已经确认的卖点，不要把模型猜测当成商品事实。</li><li>选择投放平台、创意角度和视频模型，点击 <strong>写脚本</strong>。</li><li>检查脚本里的商品外观、卖点、字幕、旁白和镜头顺序，再生成少量镜头。</li><li>在成片卡中查看播放、下载和发到画布入口，确认商品细节没有变形后再继续制作。</li></ol><p>下图上半部分是生产环境的爆款工作区，下半部分是生产广场中的公开成片结果卡，用于说明结果查看方式。当前账号的爆款工作区没有可公开的已完成商品项目，因此不把公开作品伪称为某个商品的营销成片。</p><p><a href="/abu-aigc-guide/examples/marketing-case.webp"><img src="'+s+'" alt="爆款入口与生产广场公开成片结果示例" loading="lazy"></a></p><p><em>先准备商品资料，再检查脚本和成片；公开作品只用于演示结果卡和播放入口。</em></p><h2 id="检查脚本并生成" tabindex="-1">检查脚本并生成 <a class="header-anchor" href="#检查脚本并生成" aria-label="Permalink to &quot;检查脚本并生成&quot;">​</a></h2><ol><li>点击 <strong>写脚本</strong>，等待商品信息和分镜脚本生成。</li><li>逐段检查商品外观、卖点、镜头节奏、字幕和旁白，修正不准确或不符合品牌要求的部分。</li><li>确认视频模型和参数后，先生成少量镜头检查效果，再继续完成视频。</li><li>复核生成结果中的商品细节、文案和人物动作。发布前检查平台规范与素材授权。</li></ol><p>如果 <strong>写脚本</strong> 按钮不可用，先确认已上传商品图且上传完成，并检查是否选中了可用的视频模型。仍无法提交时，请联系服务支持。</p>',19)])])}const b=e(n,[["render",p]]);export{_ as __pageData,b as default};
